#include "gui_forms/controls/tool_strip.hpp"

namespace gui_forms::detail::ic::tool_strip {

// ToolStrip::end_reserve: finite(incoming) and incoming >= 0 and incoming <= 64; else failure invalid_argument.
[[nodiscard]] constexpr bool admits_end_reserve(const double incoming) noexcept {
    const bool result = __builtin_isfinite(incoming) && (incoming >= 0) && (incoming <= 64);
    return result;
}

} // namespace gui_forms::detail::ic::tool_strip
